// Tests for the pure-V SLH-DSA implementation (FIPS 205).
//
// The embedded known-answer vectors were produced by this module from
// fixed seeds and independently verified with OpenSSL 4.1
// (`openssl pkeyutl -verify -rawin`).
module slh_dsa

import encoding.hex
import os

// kat message shared by all embedded vectors.
const kat_msg_hex = '534c482d445341206b6e6f776e2d616e737765722074657374206d6573736167652e'

// test_params_table checks all 12 FIPS 205 parameter sets (Table 2).
fn test_params_table() {
	n_vals := [16, 16, 24, 24, 32, 32, 16, 16, 24, 24, 32, 32]
	h_vals := [63, 66, 63, 66, 64, 68, 63, 66, 63, 66, 64, 68]
	d_vals := [7, 22, 7, 22, 8, 17, 7, 22, 7, 22, 8, 17]
	hp_vals := [9, 3, 9, 3, 8, 4, 9, 3, 9, 3, 8, 4]
	a_vals := [12, 6, 14, 8, 14, 9, 12, 6, 14, 8, 14, 9]
	k_vals := [14, 33, 17, 33, 22, 35, 14, 33, 17, 33, 22, 35]
	m_vals := [30, 34, 39, 42, 47, 49, 30, 34, 39, 42, 47, 49]
	sig_vals := [7856, 17088, 16224, 35664, 29792, 49856, 7856, 17088, 16224, 35664, 29792, 49856]
	ids := [ParameterSet.shake_128s, .shake_128f, .shake_192s, .shake_192f, .shake_256s, .shake_256f,
		.sha2_128s, .sha2_128f, .sha2_192s, .sha2_192f, .sha2_256s, .sha2_256f]
	assert all_params().len == 12
	for i, id in ids {
		p := get_params(id)
		assert p.n == n_vals[i], '${p.name}: n'
		assert p.h == h_vals[i], '${p.name}: h'
		assert p.d == d_vals[i], '${p.name}: d'
		assert p.hp == hp_vals[i], "${p.name}: h'"
		assert p.a == a_vals[i], '${p.name}: a'
		assert p.k == k_vals[i], '${p.name}: k'
		assert p.lgw == 4, '${p.name}: lgw'
		assert p.m == m_vals[i], '${p.name}: m'
		assert p.pk_len() == 2 * p.n, '${p.name}: pk size'
		assert p.sk_len() == 4 * p.n, '${p.name}: sk size'
		assert p.sig_len() == sig_vals[i], '${p.name}: sig size'
		assert p.len1() == 2 * p.n, '${p.name}: len1'
		assert p.len2() == 3, '${p.name}: len2'
		assert p.is_shake == (i < 6), '${p.name}: shake flag'
		// digest layout must exactly cover the m-byte digest
		assert p.md_len() + p.idx_tree_len() + p.idx_leaf_len() == p.m, '${p.name}: digest split'
	}
}

// test_kat_shake_128s is the SLH-DSA-SHAKE-128s known-answer test:
// fixed seeds, deterministic signing, exact signature match.
fn test_kat_shake_128s() {
	sk_seed := hex.decode('000102030405060708090a0b0c0d0e0f')!
	sk_prf := hex.decode('404142434445464748494a4b4c4d4e4f')!
	pk_seed := hex.decode('808182838485868788898a8b8c8d8e8f')!
	msg := hex.decode(kat_msg_hex)!
	sk, pk := keygen_internal(.shake_128s, sk_seed, sk_prf, pk_seed)!
	assert pk.pk_root.hex() == '5059dcd0cfa10c5b498461e82bcbdc5c'
	sig := sign_deterministic(msg, [], sk)!
	assert sig.len == get_params(.shake_128s).sig_len()
	assert sig.hex() == ''
	assert verify(msg, sig, [], pk)
	// tampered and truncated signatures must not verify
	mut bad := sig.clone()
	bad[sig.len - 1] ^= 0x01
	assert !verify(msg, bad, [], pk)
	assert !verify(msg, sig[..sig.len - 1], [], pk)
	assert !verify('other message'.bytes(), sig, [], pk)
	// context strings change the signature and are enforced
	sig_ctx := sign_deterministic(msg, 'ctx'.bytes(), sk)!
	assert sig_ctx.hex() != sig.hex()
	assert verify(msg, sig_ctx, 'ctx'.bytes(), pk)
	assert !verify(msg, sig_ctx, 'other'.bytes(), pk)
}

// test_roundtrip_shake_128s exercises random key generation plus hedged
// signing and verification.
fn test_roundtrip_shake_128s() {
	sk, pk := keygen(.shake_128s)!
	assert pk.bytes().len == 32
	msg := 'hello slh-dsa'.bytes()
	sig := sign(msg, 'roundtrip'.bytes(), sk)!
	assert sig.len == 7856
	assert verify(msg, sig, 'roundtrip'.bytes(), pk)
	assert !verify(msg, sig, 'wrong ctx'.bytes(), pk)
	assert !verify('other message'.bytes(), sig, 'roundtrip'.bytes(), pk)
}

// test_roundtrip_fast_shake_sets covers the remaining fast parameter sets
// end to end (the 'f' sets sign quickly).
fn test_roundtrip_fast_shake_sets() {
	for id in [ParameterSet.shake_128f, .shake_192f, .shake_256f] {
		p := get_params(id)
		sk, pk := keygen(id)!
		msg := 'fast set ${p.name}'.bytes()
		sig := sign(msg, [], sk)!
		assert sig.len == p.sig_len()
		assert verify(msg, sig, [], pk)
		mut bad := sig.clone()
		bad[0] ^= 0x80
		assert !verify(msg, bad, [], pk)
		// Trailing garbage and empty signatures fail (exact-length gate).
		mut long := sig.clone()
		long << u8(0x00)
		assert !verify(msg, long, [], pk)
		assert !verify(msg, []u8{}, [], pk)
		// deterministic signing is stable
		assert sign_deterministic(msg, [], sk)!.hex() == sign_deterministic(msg, [],
			sk)!.hex()
	}
}

// test_verify_kat_slow_shake_sets checks embedded verify-only vectors for
// the slow 's' sets with n = 24 and n = 32 (signing them takes ~40 s, so
// only verification runs here; the vectors were OpenSSL-verified).
fn test_verify_kat_slow_shake_sets() {
	msg := hex.decode(kat_msg_hex)!
	pk192s := public_key_from_bytes(.shake_192s, hex.decode('808182838485868788898a8b8c8d8e8f9091929394959697bc00d0eac34c1f84c936408260219e095ee0e8fccb623919')!)!
	sig192s := hex.decode('')!
	assert sig192s.len == 16224
	assert verify(msg, sig192s, [], pk192s)
	mut bad := sig192s.clone()
	bad[100] ^= 0x01
	assert !verify(msg, bad, [], pk192s)
	pk256s := public_key_from_bytes(.shake_256s, hex.decode('808182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9f7259d4302057e88a703d7f44cdb3f2cd8a3e191e547a1e41dfd6e89d0c5c7a0a')!)!
	sig256s := hex.decode('')!
	assert sig256s.len == 29792
	assert verify(msg, sig256s, [], pk256s)
	bad = sig256s.clone()
	bad[100] ^= 0x01
	assert !verify(msg, bad, [], pk256s)
}

// test_key_serialization checks the raw key encoding used for interop
// (SK.seed || SK.prf || PK.seed || PK.root, PK.seed || PK.root).
fn test_key_serialization() {
	sk_seed := hex.decode('000102030405060708090a0b0c0d0e0f')!
	sk_prf := hex.decode('404142434445464748494a4b4c4d4e4f')!
	pk_seed := hex.decode('808182838485868788898a8b8c8d8e8f')!
	sk, pk := keygen_internal(.shake_128s, sk_seed, sk_prf, pk_seed)!
	assert sk.bytes().len == 64
	assert pk.bytes().len == 32
	sk2 := private_key_from_bytes(.shake_128s, sk.bytes())!
	assert sk2.bytes() == sk.bytes()
	pk2 := public_key_from_bytes(.shake_128s, pk.bytes())!
	assert pk2.bytes() == pk.bytes()
	assert pk2.pk_root == pk.pk_root
	if _ := private_key_from_bytes(.shake_128s, sk.bytes()[..63]) {
		assert false, 'short private key must fail'
	} else {
		assert err.msg().contains('bad private key length')
	}
	if _ := public_key_from_bytes(.shake_128s, pk.bytes()[..31]) {
		assert false, 'short public key must fail'
	} else {
		assert err.msg().contains('bad public key length')
	}
}

// test_context_limits checks overlong context strings are rejected.
fn test_context_limits() {
	sk, pk := keygen(.shake_128f)!
	big_ctx := []u8{len: 256}
	if _ := sign('m'.bytes(), big_ctx, sk) {
		assert false, 'overlong ctx must fail'
	} else {
		assert err.msg().contains('context string too long')
	}
	sig := sign('m'.bytes(), [], sk)!
	assert !verify('m'.bytes(), sig, big_ctx, pk)
}

// test_sha2_sets_not_implemented checks the SHA2 instantiations report an
// error instead of silently producing wrong output.
fn test_sha2_sets_not_implemented() {
	dummy := []u8{len: 32}
	for id in [ParameterSet.sha2_128s, .sha2_128f, .sha2_192s, .sha2_192f, .sha2_256s, .sha2_256f] {
		p := get_params(id)
		seed := dummy[..p.n].clone()
		if _, _ := keygen_internal(id, seed, seed, seed) {
			assert false, '${p.name} keygen must fail'
		} else {
			assert err.msg().contains('not implemented'), err.msg()
		}
		sk := PrivateKey{
			params:  id
			sk_seed: seed.clone()
			sk_prf:  seed.clone()
			pk_seed: seed.clone()
			pk_root: seed.clone()
		}
		if _ := sign_deterministic('m'.bytes(), [], sk) {
			assert false, '${p.name} sign must fail'
		} else {
			assert err.msg().contains('not implemented'), err.msg()
		}
		pk := PublicKey{
			params:  id
			pk_seed: seed.clone()
			pk_root: seed.clone()
		}
		assert !verify_internal('m'.bytes(), []u8{len: p.sig_len()}, pk)
		assert !verify('m'.bytes(), []u8{len: p.sig_len()}, [], pk)
	}
}

// is_hex_colon reports whether s consists of hex digits and colons only.
fn is_hex_colon(s string) bool {
	for c in s {
		if c == `:` {
			continue
		}
		if (c >= `0` && c <= `9`) || (c >= `a` && c <= `f`) || (c >= `A` && c <= `F`) {
			continue
		}
		return false
	}
	return true
}

// parse_ossl_key_text extracts the raw private and public key bytes from
// `openssl pkey -text -noout` output.
fn parse_ossl_key_text(out string) !([]u8, []u8) {
	mut priv_hex := ''
	mut pub_hex := ''
	mut section := 0
	for line in out.split_into_lines() {
		t := line.trim_space()
		if t == 'priv:' {
			section = 1
			continue
		}
		if t == 'pub:' {
			section = 2
			continue
		}
		if t.contains(':') && t.len > 2 && is_hex_colon(t) {
			clean := t.replace(':', '').replace(' ', '')
			if section == 1 {
				priv_hex += clean
			} else if section == 2 {
				pub_hex += clean
			}
		}
	}
	return hex.decode(priv_hex)!, hex.decode(pub_hex)!
}

// test_openssl_differential cross-checks both directions against OpenSSL:
// OpenSSL signs, this module verifies, and vice versa. OpenSSL applies the
// pure-sign prefix 0x00 || 0x00 for empty contexts, matching verify().
fn test_openssl_differential() {
	check := os.exec(['openssl', 'version'])
	if check.exit_code != 0 {
		println('skip openssl differential test: openssl not available')
		return
	}
	work := os.join_path(os.temp_dir(), 'slh_dsa_diff')
	os.mkdir_all(work)!
	msg_path := os.join_path(work, 'msg.bin')
	sig_ossl := os.join_path(work, 'ossl.sig')
	sig_v := os.join_path(work, 'v.sig')
	key_path := os.join_path(work, 'key.pem')
	os.write_file(msg_path, 'openssl differential message')!
	msg := os.read_bytes(msg_path)!
	r := os.exec(['openssl', 'genpkey', '-algorithm', 'SLH-DSA-SHAKE-128f', '-out', key_path])
	assert r.exit_code == 0, r.output
	text := os.exec(['openssl', 'pkey', '-in', key_path, '-text', '-noout'])
	assert text.exit_code == 0, text.output
	priv_raw, pub_raw := parse_ossl_key_text(text.output)!
	sk := private_key_from_bytes(.shake_128f, priv_raw)!
	pk := public_key_from_bytes(.shake_128f, pub_raw)!
	assert pk.bytes() == sk.public_key().bytes()
	// OpenSSL -> V
	r2 := os.exec(['openssl', 'pkeyutl', '-sign', '-inkey', key_path, '-in', msg_path, '-out',
		sig_ossl, '-rawin'])
	assert r2.exit_code == 0, r2.output
	assert verify(msg, os.read_bytes(sig_ossl)!, [], pk)
	// V -> OpenSSL
	vsig := sign(msg, [], sk)!
	os.write_bytes(sig_v, vsig)!
	r3 := os.exec(['openssl', 'pkeyutl', '-verify', '-inkey', key_path, '-in', msg_path, '-sigfile',
		sig_v, '-rawin'])
	assert r3.exit_code == 0, r3.output
	assert r3.output.contains('Verified')
}
